<?php
declare(strict_types=1);namespace App\Http\Controllers\Hrd;use App\Http\Controllers\Controller;use App\Http\Requests\Hrd\SelfAttendanceRequest;use App\Models\PersonnelAttendance;use App\Services\Hrd\AttendanceService;use Illuminate\Http\{RedirectResponse,Request};use Illuminate\View\View;
class PersonnelAttendanceController extends Controller{public function index(Request $r):View{$q=PersonnelAttendance::with('personnel')->latest('attendance_date')->latest('check_in_time');foreach(['status','method','shift_number']as$f)if($r->filled($f))$q->where($f,$r->$f);return view('hrd.attendance.index',['title'=>'Absensi Pegawai','attendances'=>$q->paginate(20)->withQueryString()]);}public function mine(Request $r):View{$p=$r->user()->personnel;if(!$p)abort(403,'Akun belum terhubung dengan personalia.');return view('hrd.attendance.mine',['title'=>'Absensi Saya','personnel'=>$p,'attendance'=>$p->attendances()->whereDate('attendance_date',today())->first()]);}public function checkIn(SelfAttendanceRequest $r,AttendanceService $s):RedirectResponse{$p=$r->user()->personnel;if(!$p)abort(403);$s->checkIn($p,(float)$r->latitude,(float)$r->longitude,$r->user());return back()->with('status','Check-in berhasil dicatat.');}public function checkOut(SelfAttendanceRequest $r,AttendanceService $s):RedirectResponse{$p=$r->user()->personnel;if(!$p)abort(403);$s->checkOut($p,(float)$r->latitude,(float)$r->longitude,$r->user());return back()->with('status','Check-out berhasil dicatat.');}}
